  const mins = istMinutesOfDay(now);
  const start = hhmmToMinutes(cfg.sendWindowStart, 9 * 60);
  const end = hhmmToMinutes(cfg.sendWindowEnd, 12 * 60 + 30);
  if (mins < start || mins > end) return { skip: true, reason: 'OUTSIDE_SEND_WINDOW' };
  return { skip: false };
