  return { y: t.getUTCFullYear(), m: t.getUTCMonth() + 1, d: t.getUTCDate(),
           hh: t.getUTCHours(), mi: t.getUTCMinutes(), ss: t.getUTCSeconds(), dow: t.getUTCDay() };
}
function istDateStr(d) { const p = istParts(d); return `${p.y}-${pad2(p.m)}-${pad2(p.d)}`; }
function istTsStr(d) { const p = istParts(d); return `${p.y}-${pad2(p.m)}-${pad2(p.d)} ${pad2(p.hh)}:${pad2(p.mi)}:${pad2(p.ss)}`; }
function istMinutesOfDay(d) { const p = istParts(d); return p.hh * 60 + p.mi; }

// IST wall-clock → instant.
function istToDate(y, m, d, hh = 0, mi = 0, ss = 0) {
  return new Date(Date.UTC(y, m - 1, d, hh, mi, ss) - IST_OFFSET_MS);
}

// Accepts what Sheets/Gmail hand back: Date, serial number (days since
// 1899-12-30, IST wall clock), 'YYYY-MM-DD[ HH:mm[:ss]]', ISO with zone,
// 'DD/MM/YYYY[ HH:mm[:ss]]', epoch-ms strings (Gmail internalDate).
function parseTs(v) {
  if (v === null || v === undefined || v === '') return null;
  if (v instanceof Date) return isNaN(v) ? null : v;
  if (typeof v === 'number') {
    if (v > 1e11) return new Date(v);                     // epoch ms
    const ms = Math.round(v * DAY_MS);                     // sheet serial (IST wall clock)
    const base = Date.UTC(1899, 11, 30) + ms;
    return new Date(base - IST_OFFSET_MS);
  }
  const s = String(v).trim();
  if (!s) return null;
  if (/^\d{12,14}$/.test(s)) return new Date(Number(s));
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?(?:\.\d+)?)?(Z|[+-]\d{2}:?\d{2})?$/);
  if (m) {
    if (m[7]) { const p = Date.parse(s.replace(' ', 'T')); return isNaN(p) ? null : new Date(p); }
    return istToDate(+m[1], +m[2], +m[3], +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
  }
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})(?:,?\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
  if (m) return istToDate(+m[3], +m[2], +m[1], +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
  const p = Date.parse(s);
  return isNaN(p) ? null : new Date(p);
}

// 'YYYY-MM-DD' (IST) or '' for anything unparseable.
function toIstDate(v) { const d = parseTs(v); return d ? istDateStr(d) : ''; }

function dateStrToUtcNoon(s) { const [y, m, d] = s.split('-').map(Number); return Date.UTC(y, m - 1, d, 12); }
function addCalendarDays(dateStr, n) {
  const t = new Date(dateStrToUtcNoon(dateStr) + n * DAY_MS);
  return `${t.getUTCFullYear()}-${pad2(t.getUTCMonth() + 1)}-${pad2(t.getUTCDate())}`;
}
function daysBetween(a, b) { return Math.round((dateStrToUtcNoon(b) - dateStrToUtcNoon(a)) / DAY_MS); }
function dowOf(dateStr) { return new Date(dateStrToUtcNoon(dateStr)).getUTCDay(); } // 0 = Sun

// sendDays: Set of 0..6, holidays: Set of 'YYYY-MM-DD'
function isBusinessDay(dateStr, sendDays, holidays) {
  return sendDays.has(dowOf(dateStr)) && !holidays.has(dateStr);
}
function addBusinessDays(dateStr, n, sendDays, holidays) {
  let d = dateStr, left = Math.max(0, Math.round(n));
  if (left === 0) return d;
  let guard = 0;
  while (left > 0 && guard++ < 400) {
    d = addCalendarDays(d, 1);
    if (isBusinessDay(d, sendDays, holidays)) left--;
  }
  return d;
}

// Deterministic, alphanumeric-only id (safe for Telegram commands too).
function hashId(prefix, input) {
  const s = String(input || '');
  let h1 = 0x811c9dc5, h2 = 0x01000193 ^ s.length;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ c, 0x5bd1e995) >>> 0;
    h2 = (h2 ^ (h2 >>> 13)) >>> 0;
  }
  return prefix + h1.toString(36).padStart(7, '0') + (h2 % 1296).toString(36).padStart(2, '0');
}

function str(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function normEmail(v) { return str(v).toLowerCase(); }
function normUrl(v) {
  return str(v).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[?#].*$/, '').replace(/\/+$/, '');
}
function isYes(v) { return /^(y|yes|true|1)$/i.test(str(v)); }
function numOrNull(v) {
  if (v === null || v === undefined || str(v) === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}
function cmpJobIdDesc(a, b) {
  const x = str(a), y = str(b);
  if (x.length !== y.length) return y.length - x.length;
  return y < x ? -1 : y > x ? 1 : 0;
}

// ── Sheets value grids ──────────────────────────────────────────────────────
// values (2-D array, row 1 = headers) → { headers, rows } where each row has
// `_row` = 1-based sheet row number. Fully empty rows are dropped.
function parseTable(values) {
  const grid = Array.isArray(values) ? values : [];
  const headers = (grid[0] || []).map(h => str(h));
  const rows = [];
  for (let i = 1; i < grid.length; i++) {
    const r = grid[i] || [];
    if (!r.some(c => str(c) !== '')) continue;
    const o = { _row: i + 1 };
    headers.forEach((h, j) => { if (h) o[h] = r[j] === undefined ? '' : r[j]; });
    rows.push(o);
  }
  return { headers, rows, lastRow: grid.length };
}

function colLetter(idx) { // 0-based → A, B, … AA
  let s = '', n = idx + 1;
  while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); }
  return s;
}
function quoteTab(tab) { return `'${String(tab).replace(/'/g, "''")}'`; }

// One ValueRange per field, for values:batchUpdate. Unknown columns are
// skipped (and reported) rather than written somewhere wrong.
function cellWrites(tab, headers, rowNumber, fields, missing) {
  const out = [];
  for (const [k, v] of Object.entries(fields)) {
    const j = headers.indexOf(k);
    if (j < 0) { if (missing) missing.add(`${tab}.${k}`); continue; }
    out.push({ range: `${quoteTab(tab)}!${colLetter(j)}${rowNumber}`, values: [[v === null || v === undefined ? '' : v]] });
  }
  return out;
}
// A whole new row in header order.
function rowWrite(tab, headers, rowNumber, fields) {
  const row = headers.map(h => (fields[h] === undefined || fields[h] === null ? '' : fields[h]));
  return { range: `${quoteTab(tab)}!A${rowNumber}:${colLetter(Math.max(headers.length - 1, 0))}${rowNumber}`, values: [row] };
}

// valueRanges from values:batchGet → { tabName: values }
function rangesByTab(resp) {
  const out = {};
  for (const vr of (resp && resp.valueRanges) || []) {
    const tab = String(vr.range || '').split('!')[0].replace(/^'/, '').replace(/'$/, '').replace(/''/g, "'");
    out[tab] = vr.values || [];
  }
  return out;
}

// Config tab: Setting | Value | Notes (first two non-empty cells per row).
function parseConfig(values) {
  const cfg = {};
  (values || []).forEach((r, i) => {
    if (i === 0 && str(r[0]).toLowerCase() === 'setting') return;
    const k = str(r[0]);
    if (k) cfg[k] = r[1] === undefined ? '' : r[1];
  });
  return cfg;
}
function cfgNum(cfg, key, def) { const n = numOrNull(cfg[key]); return n === null ? def : n; }
function cfgStr(cfg, key, def) { const s = str(cfg[key]); return s === '' ? def : s; }
function cfgList(cfg, key, def) {
  const s = str(cfg[key]);
  return (s === '' ? def : s).split(/[,;\s]+/).map(x => x.trim()).filter(Boolean);
}
function cfgSendDays(cfg) { return new Set(cfgList(cfg, 'sendDays', '1,2,3,4,5').map(Number)); }
function cfgHolidays(cfg) { return new Set(cfgList(cfg, 'holidays', '').map(toIstDate).filter(Boolean)); }
function hhmmToMinutes(s, def) {
  const m = str(s).match(/^(\d{1,2}):(\d{2})$/);
  return m ? (+m[1]) * 60 + (+m[2]) : def;
}

function sheetsUrl(spreadsheetId) { return `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}`; }
// SERIAL_NUMBER keeps typed dates unambiguous (no locale formats); strings we
// write ourselves are RAW so they come back unchanged.
function sheetsBatchGetUrl(spreadsheetId, ranges) {
  return `${sheetsUrl(spreadsheetId)}/values:batchGet?${ranges.map(r => 'ranges=' + encodeURIComponent(r)).join('&')}` +
    '&valueRenderOption=UNFORMATTED_VALUE&dateTimeRenderOption=SERIAL_NUMBER';
}
// Column-wise batchGet (one range per column, all from row 1) → row objects.
function columnsToRows(names, valueRanges) {
  const cols = names.map((n, i) => ((valueRanges || [])[i] && valueRanges[i].values) || []);
  const len = Math.max(0, ...cols.map(c => c.length));
  const rows = [];
  for (let i = 1; i < len; i++) {
    const o = { _row: i + 1 };
    names.forEach((n, j) => { const cell = cols[j][i]; o[n] = cell && cell.length ? cell[0] : ''; });
    if (names.some(n => str(o[n]) !== '')) rows.push(o);
  }
  return rows;
}

// ── mail.js ─────────────────────────────────────────────────────────────────
// Template lookup/rendering and RFC 2822 message building for the Gmail API.
// Pure JS base64 so it works with or without Buffer in the Code-node sandbox.

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function utf8Bytes(s) {
  const out = [];
  for (const ch of String(s)) {
    let c = ch.codePointAt(0);
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}
function bytesToB64(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i], b = bytes[i + 1], c = bytes[i + 2];
    const n = (a << 16) | ((b || 0) << 8) | (c || 0);
    s += B64[(n >> 18) & 63] + B64[(n >> 12) & 63] + (b === undefined ? '=' : B64[(n >> 6) & 63]) + (c === undefined ? '=' : B64[n & 63]);
  }
  return s;
}
function b64Utf8(s) { return bytesToB64(utf8Bytes(s)); }
function b64ToUrl(b64) { return b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }
function wrap76(b64) { return (b64.match(/.{1,76}/g) || ['']).join('\r\n'); }

function encodeHeaderWord(s) {
  const v = String(s || '');
  return /^[\x20-\x7e]*$/.test(v) ? v : `=?UTF-8?B?${b64Utf8(v)}?=`;
}

// ── templates ───────────────────────────────────────────────────────────────
// templates: { CODE: { subject, body, attachResume } }. Lookup tries each code
// in order, so 'JOB_FU2' can fall back to 'JOB_FU'.
function findTemplate(templates, codes) {
  for (const c of codes) {
    const t = templates[c];
    if (t && str(t.body)) return { code: c, ...t };
  }
  return null;
}

function renderTemplate(text, ctx) {
  const filled = String(text || '').replace(/\{\{\s*(\w+)\s*\}\}/g, (_, k) => (ctx[k] === undefined || ctx[k] === null ? '' : String(ctx[k])));
  return filled
    .replace(/\r\n/g, '\n')
    .split('\n').map(l => l.replace(/[ \t]+$/, '')).join('\n')
    .replace(/\n{3,}/g, '\n\n')       // a blank placeholder line (e.g. {{PitchLine}}) leaves no gap
    .trim();
}

function replySubject(subject) {
  const s = str(subject);
  return /^re:/i.test(s) ? s : `Re: ${s}`;
}

// Returns base64url "raw" for users.messages.send / drafts.create.
function buildRawMessage({ fromName, fromEmail, to, subject, body, inReplyTo, references, attachment }) {
  const from = fromName ? `${encodeHeaderWord(fromName)} <${fromEmail}>` : fromEmail;
  const head = [
    `From: ${from}`,
    `To: ${to}`,
    `Subject: ${encodeHeaderWord(subject)}`,
    'MIME-Version: 1.0',
  ];
  if (inReplyTo) head.push(`In-Reply-To: ${inReplyTo}`);
  if (references || inReplyTo) head.push(`References: ${[references, inReplyTo].filter(Boolean).join(' ').trim()}`);
  const text = String(body || '').replace(/\r?\n/g, '\r\n');
  let mime;
  if (attachment && attachment.b64) {
    const boundary = 'b_' + hashId('', subject + to + text.length);
    const name = encodeHeaderWord(attachment.name || 'resume.pdf');
    mime = head.concat([
      `Content-Type: multipart/mixed; boundary="${boundary}"`, '',
      `--${boundary}`,
      'Content-Type: text/plain; charset="UTF-8"',
      'Content-Transfer-Encoding: base64', '',
      wrap76(b64Utf8(text)),
      `--${boundary}`,
      `Content-Type: ${attachment.mimeType || 'application/pdf'}; name="${name}"`,
      `Content-Disposition: attachment; filename="${name}"`,
      'Content-Transfer-Encoding: base64', '',
      wrap76(String(attachment.b64).replace(/\s+/g, '')),
      `--${boundary}--`, '',
    ]).join('\r\n');
  } else {
    mime = head.concat([
      'Content-Type: text/plain; charset="UTF-8"',
      'Content-Transfer-Encoding: base64', '',
      wrap76(b64Utf8(text)), '',
    ]).join('\r\n');
  }
  return b64ToUrl(bytesToB64(utf8Bytes(mime)));
}

// Gmail thread (format=metadata) → what a reply needs.
function headerOf(msg, name) {
  const hs = (msg && msg.payload && msg.payload.headers) || [];
  const h = hs.find(x => String(x.name).toLowerCase() === name.toLowerCase());
  return h ? String(h.value) : '';
}
function emailFromHeader(v) {
  const m = String(v || '').match(/<([^>]+)>/);
  return (m ? m[1] : String(v || '')).trim().toLowerCase();
}
function threadReplyInfo(thread, myEmail) {
  const msgs = ((thread && thread.messages) || []).filter(m => !(m.labelIds || []).includes('DRAFT'));
  if (!msgs.length) return null;
  const first = msgs[0], last = msgs[msgs.length - 1];
  const me = normEmail(myEmail);
  const inbound = msgs.filter(m => {
    const f = emailFromHeader(headerOf(m, 'From'));
    return f && f !== me;
  });
  return {
    subject: headerOf(first, 'Subject'),
    inReplyTo: headerOf(last, 'Message-ID') || headerOf(last, 'Message-Id'),
    references: headerOf(last, 'References'),
    lastMessageId: last.id,
    sentByMe: msgs.length - inbound.length,
    lastMineAt: (() => { const mine = msgs.filter(m => !inbound.includes(m)); return mine.length ? parseTs(mine[mine.length - 1].internalDate) : null; })(),
    inbound,
  };
}

// ── sync.js ─────────────────────────────────────────────────────────────────
// Reply / bounce / out-of-office detection. Input is Gmail threads fetched
// with format=metadata; output is state changes for the Outreach tab.
// Precedence per thread: human reply > bounce > out-of-office.

const BOUNCE_FROM = /(mailer-daemon|postmaster|mail-daemon|mail delivery (sub)?system)/i;
const BOUNCE_SUBJECT = /(delivery status notification|undeliverable|undelivered mail|mail delivery (failed|failure)|returned mail|address not found|delivery has failed|failure notice)/i;
const OOO_TEXT = /(out of (the )?office|automatic reply|auto[- ]?reply|autoreply|away from (the )?office|on (annual |parental |maternity |paternity |medical )?leave|on vacation|currently away|limited access to (my )?e-?mail)/i;

function classifyMessage(msg, myEmail) {
  if ((msg.labelIds || []).includes('DRAFT')) return null;
  const fromRaw = headerOf(msg, 'From');
  const from = emailFromHeader(fromRaw);
  if (!from || from === normEmail(myEmail)) return null;
  const subject = headerOf(msg, 'Subject');
  const snippet = str(msg.snippet);
  const failed = headerOf(msg, 'X-Failed-Recipients');
  if (BOUNCE_FROM.test(fromRaw) || failed || BOUNCE_SUBJECT.test(subject)) {
    return { kind: 'BOUNCE', failed: failed.toLowerCase().split(/[,\s]+/).filter(Boolean), snippet, at: parseTs(msg.internalDate) };
  }
  const autoSub = headerOf(msg, 'Auto-Submitted').toLowerCase();
  if ((autoSub && autoSub !== 'no') || headerOf(msg, 'X-Autoreply') || headerOf(msg, 'X-Autorespond') ||
      OOO_TEXT.test(subject) || OOO_TEXT.test(snippet.slice(0, 160))) {
    return { kind: 'OOO', from, at: parseTs(msg.internalDate) };
  }
  return { kind: 'REPLY', from, subject, snippet, at: parseTs(msg.internalDate) };
}

// threads: Gmail thread objects. outreach: parsed Outreach rows. contacts:
// parsed Contacts rows. Returns { outreachChanges: Map(outreachId → fields),
// contactChanges: Map(recruiterId → fields), events: [...] } without
// touching rows it does not change.
function syncThreads({ threads, outreach, contacts, myEmail, today, cfg }) {
  const sendDays = cfgSendDays(cfg), holidays = cfgHolidays(cfg);
  const oooDays = cfgNum(cfg, 'oooPauseDays', 5);
  const watchable = new Set(['ACTIVE', 'EXHAUSTED']);
  const byThread = new Map();
  const byEmail = new Map();
  const contactById = new Map(contacts.map(c => [str(c.recruiterId), c]));
  for (const o of outreach) {
    const st = str(o.state).toUpperCase();
    if (!watchable.has(st)) continue;
    if (str(o.threadId)) byThread.set(str(o.threadId), o);
    const c = contactById.get(str(o.recruiterId));
    if (c && normEmail(c.email)) byEmail.set(normEmail(c.email), o);
  }

  const outreachChanges = new Map(), contactChanges = new Map(), events = [];
  const verdict = new Map(); // outreachId → { kind, ... }
  const rank = { REPLY: 3, BOUNCE: 2, OOO: 1 };
  const consider = (o, v) => {
    if (!o) return;
    const prev = verdict.get(o.outreachId);
    if (!prev || rank[v.kind] > rank[prev.kind] || (v.kind === prev.kind && (v.at || 0) > (prev.at || 0))) verdict.set(o.outreachId, { ...v, o });
  };

  for (const t of threads || []) {
    if (!t || !Array.isArray(t.messages)) continue;
    const tracked = byThread.get(str(t.id));
    for (const m of t.messages) {
      const v = classifyMessage(m, myEmail);
      if (!v) continue;
      // Ignore anything older than the thread's first mail (migrated rows).
      const since = parseTs(tracked && (tracked.createdAt || tracked.lastSentAt));
      if (tracked && since && v.at && v.at < since) continue;
      if (v.kind === 'BOUNCE') {
        let target = tracked;
        const emails = v.failed.length ? v.failed : (v.snippet.match(/[\w.+-]+@[\w-]+(\.[\w-]+)+/g) || []).map(e => e.toLowerCase());
        if (!target) for (const e of emails) { if (byEmail.has(e)) { target = byEmail.get(e); break; } }
        consider(target, v);
      } else if (tracked) {
        consider(tracked, v);
      }
    }
  }

  for (const [id, v] of verdict) {
    const o = v.o;
    const st = str(o.state).toUpperCase();
    const contact = contactById.get(str(o.recruiterId)) || {};
    if (v.kind === 'REPLY') {
      outreachChanges.set(id, { state: 'REPLIED', endedAt: v.at ? istTsStr(v.at) : istTsStr(new Date()), endReason: 'REPLIED', nextSendDate: '' });
      events.push({ type: 'REPLY', outreachId: id, recruiterId: o.recruiterId, name: contact.name || o.recruiterName || '', company: contact.company || o.company || '', email: v.from, snippet: v.snippet, subject: v.subject });
    } else if (v.kind === 'BOUNCE') {
      outreachChanges.set(id, { state: 'BOUNCED', endedAt: v.at ? istTsStr(v.at) : istTsStr(new Date()), endReason: 'BOUNCED', nextSendDate: '' });
      if (str(o.recruiterId)) contactChanges.set(str(o.recruiterId), { emailStatus: 'BOUNCED' });
      events.push({ type: 'BOUNCE', outreachId: id, recruiterId: o.recruiterId, name: contact.name || '', company: contact.company || '', email: contact.email || '' });
    } else if (v.kind === 'OOO' && st === 'ACTIVE') {
      const base = v.at ? istDateStr(v.at) : today;
      const pushed = addBusinessDays(base, oooDays, sendDays, holidays);
      const current = toIstDate(o.nextSendDate);
      if (!current || current < pushed) {
        outreachChanges.set(id, { nextSendDate: pushed, note: `Out of office, paused until ${pushed}` });
        events.push({ type: 'OOO', outreachId: id, name: contact.name || '', company: contact.company || '', until: pushed });
      }
    }
  }
  return { outreachChanges, contactChanges, events };
}

// Message ids from users.messages.list → threads worth fetching.
function threadsToFetch({ recent, bounces, outreach }) {
  const tracked = new Set(outreach.filter(o => ['ACTIVE', 'EXHAUSTED'].includes(str(o.state).toUpperCase())).map(o => str(o.threadId)).filter(Boolean));
  const ids = new Set();
  for (const m of ((recent && recent.messages) || [])) if (tracked.has(str(m.threadId))) ids.add(str(m.threadId));
  for (const m of ((bounces && bounces.messages) || [])) if (str(m.threadId)) ids.add(str(m.threadId));
  return [...ids];
}

// ── send.js ─────────────────────────────────────────────────────────────────
// Per-mail steps inside the send loop: window gate → compose → record.

function gateItem({ cfg, now }) {
  if (isYes(cfg.ignoreSendWindow)) return { skip: false };
  const mins = istMinutesOfDay(now);
  const start = hhmmToMinutes(cfg.sendWindowStart, 9 * 60);
  const end = hhmmToMinutes(cfg.sendWindowEnd, 12 * 60 + 30);
  if (mins < start || mins > end) return { skip: true, reason: 'OUTSIDE_SEND_WINDOW' };
  return { skip: false };
}

function jobLooksClosed(html) {
  return /no longer accepting applications|this job is no longer available|job has expired/i.test(String(html || ''));
}

// item: a planner queue entry. thread: Gmail thread (replies only).
// resume: { b64, name, mimeType }. Returns { skip, reason } or the API call.
function composeMail({ item, cfg, thread, resume, jobClosed }) {
  const mode = cfgStr(cfg, 'mode', 'DRY_RUN').toUpperCase();
  const myEmail = cfgStr(cfg, 'myEmail', '');
  if (!myEmail) return { skip: true, reason: 'myEmail missing in Outreach Config' };
  if (!item.to) return { skip: true, reason: 'NO_EMAIL' };
  if (jobClosed) return { skip: true, reason: 'JOB_CLOSED' };
  let subject = item.subject, inReplyTo = '', references = '', threadId = '';
  if (!item.isNewThread) {
    const info = threadReplyInfo(thread, myEmail);
    if (!info) return { skip: true, reason: 'THREAD_NOT_FOUND' };
